228	                Location where = it.next();
229	                Object animal = field.getObjectAt(where);
230	                if(animal != null && animal  instanceof Actor){
231	                    Actor currentAnimal = (Actor) animal;
232	                    Integer foodValue = getFood().get(currentAnimal.getClass());
233	                    if(foodValue != null) {
234	                        if (currentAnimal instanceof Animal){
235	                            Animal current = (Animal)currentAnimal;
236	                            if(!current.getHealth()){
237	                                setUnhealthy();
238	                            }
239	                        }
240	                        currentAnimal.setDead();
241	                        setFoodLevel(foodValue + currentAnimal.getGrowthLevel());
242	                        if(getFoodLevel() > getMaxFoodLevel()){
243	                            setFoodLevel(getMaxFoodLevel() - getFoodLevel());
244	                        }
245	                        return where;
246	                    }
247	                }
248	            }
249	        }
250	        return null;
251	    }
